export const WORDMARK_ASPECT = 1581 / 382;
export const WORDMARK_VIEW = { width: 1581, height: 382 } as const;

type Box = { minX: number; minY: number; maxX: number; maxY: number };
type Part = { path: string; box: Box };

/**
 * El mismo trazado oficial, separado en sus tres piezas (por la caja de cada subtrazado):
 * la X, "periencia" y "CREATIVA". Lo usa la intro para construir el logo por partes y para
 * muestrear las partículas dentro de la X sin redibujar nada: la geometría es una sola.
 */
function splitWordmark(): { mark: Part; word: Part; tagline: Part } {
  const empty = (): Part => ({ path: "", box: { minX: Infinity, minY: Infinity, maxX: -Infinity, maxY: -Infinity } });
  const parts = { mark: empty(), word: empty(), tagline: empty() };

  for (const subpath of PATH.split(/(?=M)/)) {
    const numbers = (subpath.match(/-?\d+(?:\.\d+)?/g) ?? []).map(Number);
    const xs = numbers.filter((_, i) => i % 2 === 0);
    const ys = numbers.filter((_, i) => i % 2 === 1);
    const box = { minX: Math.min(...xs), minY: Math.min(...ys), maxX: Math.max(...xs), maxY: Math.max(...ys) };
    // "CREATIVA" es la franja inferior; la X, lo que no pasa del primer tercio; el resto, "periencia".
    const part = box.minY >= 310 ? parts.tagline : box.maxX <= 440 ? parts.mark : parts.word;
    part.path += subpath;
    part.box = {
      minX: Math.min(part.box.minX, box.minX),
      minY: Math.min(part.box.minY, box.minY),
      maxX: Math.max(part.box.maxX, box.maxX),
      maxY: Math.max(part.box.maxY, box.maxY),
    };
  }
  return parts;
}

export const WORDMARK_PARTS = splitWordmark();

export function Wordmark({ className, title }: { className?: string; title?: string }) {
  return (
    <svg
      viewBox="0 0 1581 382"
      className={className}
      role={title ? "img" : undefined}
      aria-label={title}
      aria-hidden={title ? undefined : true}
      focusable="false"
    >
      <path d={PATH} fill="currentColor" fillRule="evenodd" />
    </svg>
  );
}
